insert into public.drills (id, topic, sort, context, ko) values
('dr-m1','marketing',1,'신제품 런칭 SNS 문구','기다림은 끝났습니다. 지금 바로 만나보세요.'),
('dr-m2','marketing',2,'화장품 브랜드 슬로건','피부가 먼저 알아봅니다.'),
('dr-m3','marketing',3,'카페 시즌 메뉴 홍보','올가을, 한 잔에 담긴 계절을 느껴보세요.'),
('dr-m4','marketing',4,'앱 푸시 알림, 할인 마감 임박','할인이 곧 끝나요. 놓치지 마세요!'),
('dr-m5','marketing',5,'친환경 브랜드 소개 문장','우리는 작은 선택이 큰 변화를 만든다고 믿습니다.'),
('dr-m6','marketing',6,'고객 후기 요청 이메일 제목','고객님의 소중한 의견을 들려주세요.'),
('dr-b1','business',1,'거래처에 일정 변경 요청','부득이한 사정으로 회의 일정을 다음 주로 변경해도 될까요?'),
('dr-b2','business',2,'자료 제출 메일','요청하신 자료를 첨부해 드리니 검토 부탁드립니다.'),
('dr-b3','business',3,'회의 후 후속 메일','오늘 회의에서 논의한 내용을 정리해서 공유드립니다.'),
('dr-b4','business',4,'IR 자료 문장','당사는 올해 매출이 전년 대비 20% 증가할 것으로 예상합니다.'),
('dr-b5','business',5,'답장이 늦어 사과','답변이 늦어져서 죄송합니다.'),
('dr-b6','business',6,'협업 제안','귀사와 함께 새로운 기회를 모색하고 싶습니다.'),
('dr-d1','daily',1,'친구에게 약속 취소','미안, 오늘 갑자기 일이 생겨서 못 갈 것 같아.'),
('dr-d2','daily',2,'칭찬에 겸손하게 답하기','에이, 별거 아니야. 운이 좋았어.'),
('dr-d3','daily',3,'정신없던 하루를 마치고','오늘 진짜 정신없었어. 완전 녹초야.'),
('dr-d4','daily',4,'동네 친구에게 맛집 묻기','이 근처에 괜찮은 맛집 있어?'),
('dr-d5','daily',5,'고민 상담 중 위로','너무 자책하지 마. 누구라도 그랬을 거야.'),
('dr-d6','daily',6,'오랜만에 만난 친구','야, 이게 얼마 만이야! 하나도 안 변했네.'),
('dr-t1','travel',1,'예약 없이 식당 입장','예약은 안 했는데, 두 명 자리 있나요?'),
('dr-t2','travel',2,'호텔 체크인','체크인하려고요. 예약자 이름은 박민지입니다.'),
('dr-t3','travel',3,'길 묻기','실례지만, 여기서 역까지 걸어서 얼마나 걸리나요?'),
('dr-t4','travel',4,'식당에서 계산','따로 계산할게요. 카드 돼요?'),
('dr-t5','travel',5,'공항에서 짐이 안 나올 때','제 짐이 나오지 않았어요. 어디에 문의해야 하나요?'),
('dr-t6','travel',6,'투어 자리 문의','내일 오전 투어에 아직 자리가 남아 있나요?')
insert into public.drill_models (drill_id, best, alternatives, notes) values
('dr-m1','The wait is over. Get yours today.','["The wait is over. See it for yourself.","It''s finally here. Discover it today."]','[{"phrase":"The wait is over","why":"''기다림은 끝났다''와 짝을 이루는 관용 표현이에요. 런칭 카피에서 그대로 쓰여요."},{"phrase":"Get yours today","why":"''만나보세요''를 meet으로 직역하면 어색해요. 구매를 유도하는 카피는 get yours, discover, see for yourself를 써요."}]'),
('dr-m2','Your skin will notice first.','["Your skin knows the difference.","Feel the difference before you see it."]','[{"phrase":"notice","why":"''알아보다''를 recognize로 옮기면 사람을 알아본다는 뜻이 강해요. 변화를 느낀다는 뜻이면 notice가 맞아요."},{"phrase":"knows the difference","why":"품질 차이를 강조하는 영어 카피의 단골 표현이에요."}]'),
('dr-m3','This fall, taste the season in every cup.','["Sip the season this fall.","Autumn, in a cup."]','[{"phrase":"taste the season","why":"음료 카피에서는 ''느끼다''를 taste로 바꾸면 감각이 살아나요."},{"phrase":"fall / autumn","why":"미국은 fall, 영국과 호주는 autumn이 자연스러워요. 타깃 시장에 맞춰 고르세요."},{"phrase":"Sip the season","why":"s 소리를 반복해 리듬을 만든 카피 버전이에요."}]'),
('dr-m4','Last chance: the sale ends soon!','["Hurry, the sale ends tonight!","Don''t miss out. Time''s almost up."]','[{"phrase":"Last chance","why":"마감 임박 알림을 여는 가장 흔한 첫마디예요."},{"phrase":"Don''t miss out","why":"기회를 놓친다는 뉘앙스는 Don''t miss it보다 Don''t miss out이 맞아요."}]'),
('dr-m5','We believe small choices can make a big difference.','["We believe every small choice adds up to real change."]','[{"phrase":"make a big difference","why":"''큰 변화를 만든다''는 make a big change보다 make a big difference가 자연스러운 조합이에요."},{"phrase":"can","why":"can을 넣으면 단정하지 않고 가능성을 말해서 브랜드 톤이 부드러워져요."},{"phrase":"adds up to","why":"작은 것이 모여 큰 결과가 된다는 뜻의 구동사예요."}]'),
('dr-m6','We''d love to hear from you.','["Tell us what you think.","How did we do? Share your feedback."]','[{"phrase":"We''d love to hear from you","why":"''소중한''을 precious로 옮기면 과해요. 영어권은 따뜻하고 짧은 요청을 선호해요."},{"phrase":"How did we do?","why":"후기 요청 메일 제목으로 자주 쓰는 구어체 질문이에요."}]'),
('dr-b1','Due to unforeseen circumstances, would it be possible to move our meeting to next week?','["Something has come up on our end. Could we reschedule the meeting for next week?"]','[{"phrase":"unforeseen circumstances","why":"''부득이한 사정''에 대응하는 격식 표현이에요."},{"phrase":"Something has come up","why":"같은 뜻의 덜 딱딱한 표현이에요. 가까운 거래처에 써요."},{"phrase":"move / reschedule","why":"''변경하다''를 change로 쓰면 모호해요. 일정은 move나 reschedule을 써요."}]'),
('dr-b2','Please find attached the materials you requested for your review.','["I''ve attached the documents you asked for. Please let me know if you have any questions."]','[{"phrase":"Please find attached","why":"비즈니스 메일의 정형 표현이에요. 조금 딱딱하게 느껴지면 I''ve attached를 써요."},{"phrase":"for your review","why":"''검토 부탁드립니다''를 짧게 덧붙이는 방법이에요."}]'),
('dr-b3','Following up on today''s meeting, here is a summary of what we discussed.','["As promised, here''s a quick recap of today''s meeting."]','[{"phrase":"Following up on","why":"회의나 통화 뒤 후속 메일을 여는 표준 표현이에요."},{"phrase":"recap","why":"summary보다 가볍고 구어적인 ''정리''예요."}]'),
('dr-b4','We expect revenue to grow 20% year over year.','["We project a 20% year-on-year increase in revenue this year."]','[{"phrase":"year over year","why":"''전년 대비''의 표준 표현이에요. 영국식은 year-on-year예요."},{"phrase":"project","why":"expect보다 수치 전망이라는 느낌이 강한 IR 용어예요."},{"phrase":"We","why":"영어 IR 자료에서는 ''당사''를 the Company보다 We로 쓰는 경우가 많아요."}]'),
('dr-b5','Apologies for the delayed response.','["Sorry for the late reply.","Thank you for your patience."]','[{"phrase":"Apologies for the delayed response","why":"격식 있는 사과예요. 가까운 사이면 Sorry for the late reply로 충분해요."},{"phrase":"Thank you for your patience","why":"사과 대신 감사로 여는 방식이에요. 영어권 비즈니스 메일에서 선호돼요."}]'),
('dr-b6','We''d welcome the opportunity to explore potential collaboration with your team.','["We''re interested in exploring ways we could work together."]','[{"phrase":"explore","why":"''모색하다''에 딱 맞는 동사예요. seek보다 부드러워요."},{"phrase":"your team","why":"''귀사''는 your company도 되지만 your team이 더 친근하고 요즘 메일에서 흔해요."}]'),
('dr-d1','Sorry, something came up and I don''t think I can make it today.','["I''m so sorry, I have to bail tonight. Something came up."]','[{"phrase":"something came up","why":"''갑자기 일이 생기다''의 가장 자연스러운 표현이에요. 이유를 자세히 말하지 않아도 돼요."},{"phrase":"make it","why":"약속에 ''가다, 참석하다''는 go보다 make it이 자연스러워요."},{"phrase":"bail","why":"''약속을 펑크 내다''의 구어예요. 친한 사이에서만 써요."}]'),
('dr-d2','Oh, it was nothing. I just got lucky.','["Thanks, but honestly I just got lucky."]','[{"phrase":"it was nothing","why":"겸손하게 칭찬을 넘기는 관용 표현이에요."},{"phrase":"Thanks, but ~","why":"영어권에서는 칭찬을 부정하기보다 먼저 고맙다고 받는 게 자연스러워요."}]'),
('dr-d3','Today was so hectic. I''m completely wiped out.','["What a crazy day. I''m exhausted."]','[{"phrase":"hectic","why":"''정신없는''에 가장 가까운 형용사예요."},{"phrase":"wiped out","why":"''녹초가 되다''의 구어예요. beat, drained도 써요."}]'),
('dr-d4','Do you know any good places to eat around here?','["Any good restaurant recommendations nearby?"]','[{"phrase":"good places to eat","why":"''맛집''에 딱 맞는 영어 단어가 없어서 풀어서 말해요."},{"phrase":"around here","why":"''이 근처''는 near here보다 around here가 흔해요."}]'),
('dr-d5','Don''t be too hard on yourself. Anyone would have done the same.','["Go easy on yourself. It could''ve happened to anyone."]','[{"phrase":"be hard on yourself","why":"''자책하다''의 자연스러운 표현이에요. blame yourself보다 부드러워요."},{"phrase":"would have done","why":"''누구라도 그랬을 거야''는 가정법 과거완료로 말해요."}]'),
('dr-d6','Wow, it''s been ages! You haven''t changed a bit.','["Long time no see! You look exactly the same."]','[{"phrase":"it''s been ages","why":"''이게 얼마 만이야''에 해당하는 자연스러운 감탄이에요."},{"phrase":"not ~ a bit","why":"''하나도 안''을 강조하는 표현이에요."}]'),
('dr-t1','We don''t have a reservation. Do you have a table for two?','["Hi, just the two of us, no reservation. Is there anything available?"]','[{"phrase":"a table for two","why":"식당에서 인원을 말하는 정형 표현이에요."},{"phrase":"reservation","why":"미국은 reservation, 영국은 booking도 많이 써요."}]'),
('dr-t2','Hi, I''d like to check in. The reservation is under Minji Park.','["Checking in, please. It''s under Park."]','[{"phrase":"under (이름)","why":"''~ 이름으로 된 예약''은 전치사 under를 써요."},{"phrase":"I''d like to","why":"I want to보다 공손한 요청이에요."}]'),
('dr-t3','Excuse me, how long does it take to walk to the station from here?','["Excuse me, is the station within walking distance?"]','[{"phrase":"how long does it take","why":"걸리는 시간을 묻는 기본 틀이에요."},{"phrase":"within walking distance","why":"''걸어갈 만한 거리''라는 유용한 표현이에요."}]'),
('dr-t4','Could we pay separately? Do you take card?','["Can we split the bill? Is card okay?"]','[{"phrase":"pay separately / split the bill","why":"separately는 각자 먹은 것을 내는 것, split the bill은 금액을 나눠 내는 뉘앙스예요."},{"phrase":"Do you take card?","why":"''카드 돼요?''의 자연스러운 표현이에요. Do you accept cards?는 조금 더 격식 있어요."}]'),
('dr-t5','My luggage didn''t come out. Where should I report it?','["My bag hasn''t arrived. Where''s the lost baggage desk?"]','[{"phrase":"luggage / baggage","why":"둘 다 셀 수 없는 명사예요. 가방 하나를 말할 땐 my bag이 자연스러워요."},{"phrase":"report","why":"분실을 ''문의하다, 신고하다''라고 할 땐 report를 써요."}]'),
('dr-t6','Are there any spots left on tomorrow morning''s tour?','["Is tomorrow''s morning tour fully booked?"]','[{"phrase":"spots left","why":"''남은 자리''를 구어로는 spots, 격식 있게는 seats나 availability라고 해요."},{"phrase":"fully booked","why":"매진인지 묻는 반대 방향 질문이에요."}]')
